// Gera array de páginas (100 registros por página)
// 716 membros = 8 páginas, geramos até 10 por segurança
const paginas = [];
for (let i = 0; i <= 10; i++) {
  paginas.push({ json: { pagina: i } });
}
return paginas;

// Extrai registros de todas as páginas e normaliza
// Importa apenas FREQUENTADORES
const resultados = [];

for (const item of $input.all()) {
  const registros = item.json.registros || [];
  for (const r of registros) {
    // Exclui membros inativos
    const arrolamento = (r.descricaoArrolamento || '').trim().toUpperCase();
    const inativo = arrolamento.startsWith('DEMISSAO') ||
                    arrolamento === 'CRIANÇAS APRESENTADAS NA IGREJA' ||
                    arrolamento === 'FAMILIAS ASSISTIDAS PELA IGREJA';
    if (inativo) continue;

    const celularRaw = r.celular || '';
    const digits = celularRaw.replace(/\D/g, '');
    const celularWA = digits.length >= 10
      ? (digits.startsWith('55') ? digits : '55' + digits)
      : '';

    resultados.push({ json: {
      codigo:           r.codigo,
      nome:             r.nome || '',
      celular:          celularRaw,
      celular_whatsapp: celularWA,
      email:            r.email || '',
      sexo:             r.sexo || '',
      arrolamento:      r.descricaoArrolamento || '',
      data_arrolamento: r.dataArrolamento ? r.dataArrolamento.substring(0, 10) : null,
      igreja:           r.descricaoIgreja || ''
    }});
  }
}

return resultados.length > 0 ? resultados : [];
